/**
 * Dyslipidemia Decision Support Logic
 * Based on 2026 ACC/AHA/AACVPR/ABC/ACPM/ADA/AGS/APhA/ASPC/NLA/PCNA Guideline
 * on the Management of Dyslipidemia
 */

export type PreventionCategory = "primordial" | "primary" | "secondary";
export type RiskLevel = "very-high" | "high" | "moderate" | "low";
export type StatinIntensity = "high" | "moderate" | "low" | "none";

export interface LipidPanel {
  ldlC: number; // mg/dL
  hdlC: number; // mg/dL
  triglycerides: number; // mg/dL
  totalCholesterol: number; // mg/dL
  lpa?: number; // nmol/L or mg/dL (optional)
}

export interface PatientData {
  age: number;
  sex: "male" | "female";
  smoker: boolean;
  diabetic: boolean;
  hypertensive: boolean;
  familyHistoryPrematureCAD: boolean;
  priorMI: boolean;
  priorStroke: boolean;
  priorPAD: boolean;
  aorticAneurysm: boolean;
  eGFR?: number; // mL/min/1.73m2
  albuminuria?: boolean;
  lipidPanel: LipidPanel;
}

export interface DyslipidemiaTreatmentPlan {
  preventionCategory: PreventionCategory;
  riskLevel: RiskLevel;
  ldlCGoal: number;
  statinIntensity: StatinIntensity;
  statinRecommendation: string;
  nonStatinTherapies: string[];
  lipaRecommendation?: string;
  monitoringInterval: string;
  reasoning: string;
}

/**
 * Determine prevention category based on patient history
 */
export function determinePreventionCategory(patient: PatientData): PreventionCategory {
  if (patient.priorMI || patient.priorStroke || patient.priorPAD || patient.aorticAneurysm) {
    return "secondary";
  }
  if (patient.diabetic || patient.age >= 40) {
    return "primary";
  }
  return "primordial";
}

/**
 * Calculate 10-year ASCVD risk using pooled cohort equations
 * Simplified version for risk stratification
 */
export function calculateASCVDRisk(patient: PatientData): number {
  let risk = 0;

  // Age contribution
  if (patient.sex === "male") {
    risk += (patient.age - 45) * 0.5;
  } else {
    risk += (patient.age - 55) * 0.5;
  }

  // Cholesterol contribution
  risk += (patient.lipidPanel.totalCholesterol - 170) * 0.02;

  // HDL contribution
  risk -= (patient.lipidPanel.hdlC - 50) * 0.03;

  // Smoking
  if (patient.smoker) risk += 5;

  // Diabetes
  if (patient.diabetic) risk += 3;

  // Hypertension
  if (patient.hypertensive) risk += 2;

  // Family history
  if (patient.familyHistoryPrematureCAD) risk += 2;

  return Math.max(0, Math.min(100, risk));
}

/**
 * Determine cardiovascular risk level based on patient data and lipids
 */
export function determineRiskLevel(patient: PatientData, preventionCategory: PreventionCategory): RiskLevel {
  // Secondary prevention (ASCVD present)
  if (preventionCategory === "secondary") {
    return "very-high";
  }

  // High-risk conditions in primary prevention
  if (preventionCategory === "primary") {
    // Severe hypercholesterolemia (LDL-C ≥190 mg/dL)
    if (patient.lipidPanel.ldlC >= 190) {
      return "very-high";
    }

    // Diabetes with additional risk factors
    if (patient.diabetic) {
      if (patient.age >= 40 || patient.smoker || patient.hypertensive) {
        return "high";
      }
      return "moderate";
    }

    // 10-year ASCVD risk ≥7.5%
    const ascvdRisk = calculateASCVDRisk(patient);
    if (ascvdRisk >= 7.5) {
      return "high";
    }

    // 10-year ASCVD risk 5-7.5%
    if (ascvdRisk >= 5) {
      return "moderate";
    }

    return "low";
  }

  // Primordial prevention
  return "low";
}

/**
 * Determine LDL-C treatment goal based on risk level
 */
export function determineLDLCGoal(riskLevel: RiskLevel): number {
  switch (riskLevel) {
    case "very-high":
      return 55; // <55 mg/dL
    case "high":
      return 70; // <70 mg/dL
    case "moderate":
      return 100; // <100 mg/dL
    case "low":
      return 130; // <130 mg/dL
  }
}

/**
 * Determine statin intensity based on risk level and LDL-C
 */
export function determineStatinIntensity(riskLevel: RiskLevel, ldlC: number, ldlCGoal: number): StatinIntensity {
  if (riskLevel === "very-high") {
    return "high";
  }

  if (riskLevel === "high") {
    return ldlC > ldlCGoal ? "high" : "moderate";
  }

  if (riskLevel === "moderate") {
    return ldlC > ldlCGoal ? "moderate" : "low";
  }

  return ldlC > ldlCGoal ? "low" : "none";
}

/**
 * Get statin recommendation with specific agent
 */
export function getStatinRecommendation(intensity: StatinIntensity): string {
  switch (intensity) {
    case "high":
      return "High-intensity statin: Atorvastatin 40-80 mg daily or Rosuvastatin 20-40 mg daily";
    case "moderate":
      return "Moderate-intensity statin: Atorvastatin 10-20 mg daily, Rosuvastatin 5-10 mg daily, or Simvastatin 20-40 mg daily";
    case "low":
      return "Low-intensity statin: Simvastatin 10 mg daily, Pravastatin 10-20 mg daily, or Lovastatin 20 mg daily";
    case "none":
      return "Statin therapy not indicated at this time; focus on lifestyle modifications";
  }
}

/**
 * Recommend non-statin therapies based on risk and LDL-C response
 */
export function recommendNonStatinTherapies(
  riskLevel: RiskLevel,
  ldlC: number,
  ldlCGoal: number,
  lpa?: number
): string[] {
  const therapies: string[] = [];

  // If LDL-C not at goal despite statin
  if (ldlC > ldlCGoal) {
    therapies.push("Ezetimibe 10 mg daily (reduces LDL-C by 15-20%)");

    if (riskLevel === "very-high" || riskLevel === "high") {
      therapies.push("PCSK9 inhibitor (evolocumab, alirocumab, inclisiran) - reduces LDL-C by 40-60%");
      therapies.push("Bempedoic acid 120 mg daily (reduces LDL-C by 13-15%, uric acid lowering)");
    }
  }

  // Elevated Lp(a) management
  if (lpa && lpa > 50) {
    therapies.push("Inclisiran (PCSK9i) - particularly effective for elevated Lp(a)");
    therapies.push("Consider lipoprotein(a) apheresis if Lp(a) >200 nmol/L and very high risk");
  }

  // Elevated triglycerides
  if (ldlC <= ldlCGoal && ldlC > 0) {
    // Calculate non-HDL-C
    const nonHdlC = ldlC + (ldlC > 0 ? 0 : 0); // Simplified
    if (nonHdlC > ldlCGoal + 30) {
      therapies.push("Icosapent ethyl 2-4 g daily (if triglycerides 135-499 mg/dL despite statin)");
      therapies.push("GLP-1 receptor agonist (if diabetic or overweight)");
    }
  }

  return therapies;
}

/**
 * Generate comprehensive dyslipidemia treatment plan
 */
export function generateDyslipidemiaPlan(patient: PatientData): DyslipidemiaTreatmentPlan {
  const preventionCategory = determinePreventionCategory(patient);
  const riskLevel = determineRiskLevel(patient, preventionCategory);
  const ldlCGoal = determineLDLCGoal(riskLevel);
  const statinIntensity = determineStatinIntensity(riskLevel, patient.lipidPanel.ldlC, ldlCGoal);
  const statinRecommendation = getStatinRecommendation(statinIntensity);
  const nonStatinTherapies = recommendNonStatinTherapies(riskLevel, patient.lipidPanel.ldlC, ldlCGoal, patient.lipidPanel.lpa);

  let reasoning = "";

  if (preventionCategory === "secondary") {
    reasoning = `Patient has established ASCVD (${
      patient.priorMI ? "prior MI, " : ""
    }${patient.priorStroke ? "prior stroke, " : ""}${patient.priorPAD ? "prior PAD, " : ""}${
      patient.aorticAneurysm ? "aortic aneurysm" : ""
    }). Very high-risk category with LDL-C goal <55 mg/dL.`;
  } else if (preventionCategory === "primary") {
    if (patient.lipidPanel.ldlC >= 190) {
      reasoning = `Severe hypercholesterolemia (LDL-C ${patient.lipidPanel.ldlC} mg/dL). Very high-risk category with LDL-C goal <55 mg/dL.`;
    } else if (patient.diabetic) {
      reasoning = `Diabetic patient with ${riskLevel} risk. LDL-C goal <${ldlCGoal} mg/dL.`;
    } else {
      const ascvdRisk = calculateASCVDRisk(patient);
      reasoning = `Primary prevention with ${riskLevel} risk (10-year ASCVD risk ~${ascvdRisk.toFixed(1)}%). LDL-C goal <${ldlCGoal} mg/dL.`;
    }
  } else {
    reasoning = `Primordial prevention. Focus on lifestyle modifications and risk factor reduction. LDL-C goal <${ldlCGoal} mg/dL.`;
  }

  const lipaRecommendation =
    patient.lipidPanel.lpa && patient.lipidPanel.lpa > 50
      ? `Elevated Lp(a) (${patient.lipidPanel.lpa} nmol/L). Consider PCSK9i or inclisiran for additional Lp(a) reduction.`
      : undefined;

  return {
    preventionCategory,
    riskLevel,
    ldlCGoal,
    statinIntensity,
    statinRecommendation,
    nonStatinTherapies,
    lipaRecommendation,
    monitoringInterval: riskLevel === "very-high" ? "4-12 weeks" : riskLevel === "high" ? "4-12 weeks" : "3-6 months",
    reasoning,
  };
}
